var n=`0494-harak-osbao`;var t=`world-0494`;var a=`SY`;var o=`western-asia`;var s=4;var r=44;var l={en:`Harak Osbao`,ua:`Харак осбао`};var g={en:`A traditional dish from Syria, centered on yellow onion, green lentils, wheat noodles, lemon juice. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Сирія. Основні складники: жовта цибуля, зелена сочевиця, пшенична локшина, лимонний сік. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,230,`g`],[`extra-virgin-olive-oil`,60,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 18 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 18 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:18,i:[[`green-lentils`,280,`g`],[`water`,1100,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 12 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 12 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:12,i:[[`wheat-noodles`,220,`g`],[`lemon-juice`,50,`ml`],[`pomegranate-molasses`,65,`ml`],[`garlic`,4,`clove`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`cilantro`,30,`g`],[`pita-bread`,3,`pcs`]]}];var m={slug:n,id:t,country:`SY`,region:o,servings:4,minutes:44,title:l,text:g,steps:d};export{a as country,m as default,t as id,r as minutes,o as region,s as servings,n as slug,d as steps,g as text,l as title};